export const CATEGORIES=['Family','Friend','Pet'];
export const MAX_FILE_SIZE=25*1024*1024;
export function validateFiles(files){if(files.length>12)throw Error('Choose up to 12 files at a time.');for(const f of files){if(!/^(image\/(jpeg|png|webp|gif)|video\/(mp4|webm)|audio\/(mpeg|mp4|wav|x-wav|ogg|webm))$/.test(f.type))throw Error('Use JPG, PNG, WebP, GIF, MP4, WebM, MP3, WAV or OGG files.');if(f.size>MAX_FILE_SIZE)throw Error('Each file must be 25 MB or smaller.');}return true;}
export function filterMemories(items,{category='All',query='',favorites=false}={}){const q=query.trim().toLowerCase();return items.filter(m=>(category==='All'||m.category===category)&&(!favorites||m.favorite)&&(!q||[m.title,m.story,m.category].join(' ').toLowerCase().includes(q)));}
export function cleanMemory(data){const title=String(data.title||'').trim();if(!title||title.length>100)throw Error('Add a title of 1–100 characters.');if(!CATEGORIES.includes(data.category))throw Error('Choose a valid category.');const story=String(data.story||'').trim();if(story.length>5000)throw Error('Please keep your story under 5,000 characters.');if(data.date&&!/^\d{4}-\d{2}-\d{2}$/.test(data.date))throw Error('Choose a valid date.');return {title,story,category:data.category,date:data.date||new Date().toISOString().slice(0,10)};}
let dbPromise;
function db(){return dbPromise??=new Promise((resolve,reject)=>{const request=indexedDB.open('remember-v1',1);request.onupgradeneeded=()=>request.result.createObjectStore('memories',{keyPath:'id'});request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(Error('Your browser could not open local storage. Please use a regular browser window.'));});}
export async function allMemories(){const d=await db();return new Promise((resolve,reject)=>{const t=d.transaction('memories');const r=t.objectStore('memories').getAll();r.onsuccess=()=>resolve(r.result.sort((a,b)=>b.createdAt-a.createdAt));r.onerror=()=>reject(r.error);});}
export async function putMemories(items){const d=await db();return new Promise((resolve,reject)=>{const t=d.transaction('memories','readwrite');for(const m of items)t.objectStore('memories').put(m);t.oncomplete=()=>resolve();t.onerror=()=>reject(t.error);t.onabort=()=>reject(t.error||Error('Storage is full. Export your memories before freeing space.'));});}
export async function removeMemory(id){const d=await db();return new Promise((resolve,reject)=>{const t=d.transaction('memories','readwrite');t.objectStore('memories').delete(id);t.oncomplete=resolve;t.onerror=()=>reject(t.error);});}
export function readSettings(){try{return {name:'Your space',sound:false,motion:!globalThis.matchMedia?.('(prefers-reduced-motion: reduce)').matches,scene:'room',...JSON.parse(localStorage.getItem('remember-settings')||'{}')};}catch{return {name:'Your space',sound:false,motion:false,scene:'room'};}}
export function writeSettings(s){localStorage.setItem('remember-settings',JSON.stringify(s));}
